-- FILMES
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('que-horas-ela-volta','Que Horas Ela Volta?',2015,'Anna Muylaert',7.7,'Val é empregada doméstica e vive na casa dos patrões até a chegada da filha Jéssica, que recusa os lugares invisíveis reservados a elas.','Mostra como hierarquias sociais são naturalizadas no cotidiano brasileiro. Serve a temas de desigualdade, trabalho e mobilidade via educação.','Como retrata Que Horas Ela Volta? (2015), as desigualdades brasileiras se sustentam em regras não escritas que definem quem pode ocupar cada espaço.','introducao','from-amber-500/30 to-rose-700/40','https://upload.wikimedia.org/wikipedia/pt/7/78/Que_horas_ela_volta_ver3_xlg.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('cidade-de-deus','Cidade de Deus',2002,'Fernando Meirelles',8.6,'A trajetória de jovens em uma favela carioca entre os anos 1960 e 1980, marcada pela expansão do tráfico e pela ausência do Estado.','Use para abandono estatal, ciclos de violência e criminalização da pobreza, combinando com o Atlas da Violência.','Cidade de Deus (2002) evidencia que, onde o Estado só chega pela força policial, a violência vira a única via de reconhecimento social.','desenvolvimento','from-orange-600/40 to-red-900/50','https://upload.wikimedia.org/wikipedia/pt/1/10/CidadedeDeus.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('estrelas-alem-do-tempo','Estrelas Além do Tempo',2016,'Theodore Melfi',7.8,'Três cientistas negras enfrentam a segregação racial na NASA dos anos 1960 enquanto viabilizam a corrida espacial americana.','Ótimo para representatividade, ciência e trabalho feminino: talento sem oportunidade não basta.','Estrelas Além do Tempo (2016) escancara que barreiras institucionais, e não a falta de mérito, afastaram mulheres negras da ciência.','desenvolvimento','from-sky-500/30 to-indigo-800/50','https://upload.wikimedia.org/wikipedia/pt/4/4b/Hidden_Figures.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('o-dilema-das-redes','O Dilema das Redes',2020,'Jeff Orlowski',7.6,'Ex-executivos do Vale do Silício explicam como algoritmos são desenhados para capturar atenção e moldar comportamento.','Repertório certeiro para internet, fake news, privacidade e saúde mental de adolescentes.','O Dilema das Redes (2020) alerta que, quando a atenção vira mercadoria, o usuário deixa de ser cliente e passa a ser produto.','desenvolvimento','from-cyan-500/30 to-slate-900/60','https://upload.wikimedia.org/wikipedia/en/2/27/Social_dilemma_xlg.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('central-do-brasil','Central do Brasil',1998,'Walter Salles',8,'Dora escreve cartas para analfabetos na estação Central do Brasil e cruza o país com um menino em busca do pai.','Ideal para educação de adultos, migração interna e invisibilidade social.','Em Central do Brasil (1998), o analfabetismo aparece como mudez social: quem não escreve depende sempre da voz de outro.','introducao','from-yellow-600/30 to-emerald-900/50','https://upload.wikimedia.org/wikipedia/pt/2/29/Central_do_Brasil_poster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('tempos-modernos','Tempos Modernos',1936,'Charles Chaplin',8.5,'Um operário é engolido pela linha de produção e pela lógica de vigilância do trabalho industrial.','Clássico para trabalho, automação, inteligência artificial e desemprego tecnológico.','Tempos Modernos (1936) antecipa o risco de uma sociedade em que a técnica avança mais rápido que a proteção ao trabalhador.','conclusao','from-zinc-400/30 to-zinc-900/60','https://upload.wikimedia.org/wikipedia/commons/thumb/3/36/Modern_Times_poster.jpg/500px-Modern_Times_poster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('a-onda','A Onda',2008,'Dennis Gansel',7.6,'Um experimento escolar sobre autocracia sai do controle e revela como um grupo comum adere ao pensamento coletivo.','Forte para democracia, intolerância, extremismo e comportamento de massa.','A Onda (2008) mostra que o autoritarismo não nasce pronto: instala-se pela adesão silenciosa da maioria.','desenvolvimento','from-red-600/30 to-neutral-900/60','https://upload.wikimedia.org/wikipedia/pt/2/21/Die_Welle_%28A_Onda%29.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('wall-e','WALL·E',2008,'Andrew Stanton',8.4,'Em uma Terra soterrada por lixo, um robô segue compactando resíduos enquanto a humanidade vive alienada no espaço.','Sustentabilidade, consumo excessivo, resíduos sólidos e sedentarismo.','WALL·E (2008) projeta o desfecho de um consumo sem limites: um planeta transformado em depósito.','conclusao','from-amber-400/30 to-teal-900/50','https://upload.wikimedia.org/wikipedia/pt/3/30/WALL-E.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('coringa','Coringa',2019,'Todd Phillips',8.3,'Arthur Fleck, sem acesso a tratamento psiquiátrico e humilhado socialmente, desliza para a violência.','Saúde mental, desamparo estatal e estigma; combine com dados da OMS.','Coringa (2019) evidencia o custo social de negligenciar a saúde mental: o sofrimento privado vira colapso coletivo.','desenvolvimento','from-violet-600/30 to-emerald-900/50','https://upload.wikimedia.org/wikipedia/pt/6/63/Joker_%282019%29.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('historias-cruzadas','Histórias Cruzadas',2011,'Tate Taylor',8.1,'Empregadas negras no Mississippi segregado dos anos 1960 contam suas histórias e desafiam a ordem racial local.','Racismo estrutural, trabalho doméstico e narrativa como resistência.','Histórias Cruzadas (2011) mostra que dar nome à injustiça é o primeiro passo para desmontá-la.','conclusao','from-rose-400/30 to-amber-900/50','https://upload.wikimedia.org/wikipedia/pt/b/b5/Help_poster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('ilha-das-flores','Ilha das Flores',1989,'Jorge Furtado',8.4,'Curta-metragem que segue o trajeto de um tomate até um lixão, expondo a hierarquia entre pessoas, porcos e dinheiro.','Um dos repertórios mais eficientes para fome, desigualdade e descarte de alimentos.','Ilha das Flores (1989) revela uma sociedade em que o acesso à comida é definido pelo dinheiro, e não pela humanidade.','introducao','from-lime-500/30 to-stone-900/60','https://upload.wikimedia.org/wikipedia/pt/5/56/Ilha_das_flores_intro.png');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('bacurau','Bacurau',2019,'Kleber Mendonça Filho',7.4,'Um povoado do sertão desaparece do mapa e passa a ser caçado por estrangeiros, enquanto a comunidade se organiza.','Apagamento de comunidades, coronelismo, água e resistência coletiva.','Bacurau (2019) alerta que comunidades apagadas dos mapas oficiais são as primeiras a perder direitos.','desenvolvimento','from-red-500/30 to-yellow-900/50','https://upload.wikimedia.org/wikipedia/pt/6/67/Bacurau_%28filme%29.jpeg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('marighella','Marighella',2021,'Wagner Moura',6.5,'A trajetória de Carlos Marighella na resistência armada à ditadura militar brasileira.','Memória histórica, autoritarismo e importância das instituições democráticas.','Marighella (2021) reforça que a memória da ditadura é a principal vacina contra sua repetição.','conclusao','from-red-700/40 to-zinc-900/60','https://upload.wikimedia.org/wikipedia/en/c/ca/Marighella_poster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('olga','Olga',2004,'Jayme Monjardim',7.2,'A militante Olga Benário é entregue pelo governo Vargas à Alemanha nazista, grávida e perseguida.','Direitos humanos, papel do Estado e violência política contra mulheres.','Olga (2004) recorda que Estados também podem ser autores de violações de direitos humanos.','desenvolvimento','from-rose-700/40 to-slate-900/60','https://upload.wikimedia.org/wikipedia/pt/0/03/Capa_d%27filme_Olga.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('carandiru','Carandiru',2003,'Hector Babenco',7.5,'Um médico narra o cotidiano da maior penitenciária da América Latina até o massacre de 1992.','Superlotação carcerária, ressocialização e violência institucional.','Carandiru (2003) expõe um sistema prisional que pune sem ressocializar e devolve às ruas o que agravou.','desenvolvimento','from-stone-500/30 to-red-900/50','https://upload.wikimedia.org/wikipedia/pt/1/17/Carandiru_filme.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('preciosa','Preciosa',2009,'Lee Daniels',7.3,'Uma adolescente negra vítima de abusos encontra na escola alternativa uma chance de recomeço.','Educação como via de emancipação, violência intrafamiliar e assistência social.','Preciosa (2009) demonstra que a escola pode ser o único espaço de proteção para quem vive a violência dentro de casa.','introducao','from-fuchsia-600/30 to-slate-900/60','https://upload.wikimedia.org/wikipedia/pt/4/4a/Precious_teaser_1sht-3.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('laranja-mecanica','Laranja Mecânica',1971,'Stanley Kubrick',8.2,'Alex é submetido a um tratamento estatal que anula sua capacidade de escolher entre o bem e o mal.','Limites do poder estatal, punitivismo e livre-arbítrio.','Laranja Mecânica (1971) questiona um Estado que corrige comportamentos sem transformar as causas da violência.','conclusao','from-orange-500/30 to-indigo-900/60','https://upload.wikimedia.org/wikipedia/pt/7/73/A_Clockwork_Orange_%281971%29.png');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('o-poco','O Poço',2019,'Galder Gaztelu-Urrutia',7,'Uma prisão vertical distribui comida de cima para baixo e revela o comportamento humano diante da escassez.','Metáfora direta de concentração de renda e de solidariedade como saída coletiva.','O Poço (2019) traduz a lógica da concentração de renda: quem está no topo se serve primeiro e decide o que sobra.','introducao','from-slate-400/30 to-red-950/60','https://upload.wikimedia.org/wikipedia/pt/5/50/El_hoyo.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('parasita','Parasita',2019,'Bong Joon-ho',8.5,'Uma família pobre se infiltra na rotina de uma família rica, até que a arquitetura social cobra seu preço.','Desigualdade, moradia e precarização do trabalho em contexto global.','Parasita (2019) mostra que a desigualdade não é apenas econômica: é também espacial, entre o subsolo e a colina.','desenvolvimento','from-emerald-500/30 to-zinc-900/60','https://upload.wikimedia.org/wikipedia/pt/b/be/Parasite_poster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('nao-olhe-para-cima','Não Olhe Para Cima',2021,'Adam McKay',7.2,'Cientistas tentam alertar o mundo sobre um cometa e esbarram na política, na mídia e nas redes.','Negacionismo científico, crise climática e papel da mídia.','Não Olhe Para Cima (2021) satiriza sociedades que transformam consenso científico em opinião negociável.','desenvolvimento','from-blue-500/30 to-fuchsia-900/50','https://upload.wikimedia.org/wikipedia/pt/5/5c/Don%27t_Look_Up_2021_film.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('ela','Ela',2013,'Spike Jonze',8,'Theodore se apaixona por um sistema operacional e revela a solidão de uma vida mediada por telas.','Relações virtuais, inteligência artificial e solidão contemporânea.','Ela (2013) antecipa uma sociedade em que a companhia algorítmica substitui o vínculo humano.','introducao','from-rose-500/30 to-orange-900/50','https://upload.wikimedia.org/wikipedia/pt/9/9b/Her.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('tempo-de-recomecar','O Menino que Descobriu o Vento',2019,'Chiwetel Ejiofor',7.6,'Um garoto malauiano constrói um moinho de vento com sucata para salvar sua aldeia da seca.','Educação, inovação social e acesso à energia e à água.','O Menino que Descobriu o Vento (2019) prova que ciência acessível transforma realidades locais.','conclusao','from-emerald-400/30 to-sky-900/50','https://upload.wikimedia.org/wikipedia/pt/4/44/The_Boy_Who_Harnessed_the_Wind.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('uma-mente-brilhante','Uma Mente Brilhante',2001,'Ron Howard',8.2,'O matemático John Nash convive com a esquizofrenia enquanto revoluciona a teoria dos jogos.','Saúde mental, estigma e inclusão de pessoas com transtornos.','Uma Mente Brilhante (2001) mostra que suporte social é decisivo no tratamento de transtornos mentais.','desenvolvimento','from-indigo-400/30 to-slate-900/60','https://upload.wikimedia.org/wikipedia/pt/b/b1/UmaMenteBrilhante.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('o-clube-do-imperador','Sociedade dos Poetas Mortos',1989,'Peter Weir',8.1,'Um professor desafia o método tradicional de um colégio rígido e ensina alunos a pensar por si mesmos.','Modelos de ensino, saúde mental na juventude e autonomia intelectual.','Sociedade dos Poetas Mortos (1989) defende uma educação que forme sujeitos críticos, não repetidores.','conclusao','from-amber-500/30 to-emerald-950/60','https://upload.wikimedia.org/wikipedia/pt/0/04/Dead_Poets_Society.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('hotel-ruanda','Hotel Ruanda',2004,'Terry George',8.1,'Um gerente de hotel abriga mais de mil refugiados durante o genocídio em Ruanda.','Intolerância étnica, omissão internacional e refúgio.','Hotel Ruanda (2004) denuncia que a omissão da comunidade internacional também mata.','desenvolvimento','from-orange-500/30 to-stone-900/60','https://upload.wikimedia.org/wikipedia/pt/b/bf/Hotel_Ruanda.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('a-vida-e-bela','A Vida é Bela',1997,'Roberto Benigni',8.6,'Um pai transforma o horror de um campo de concentração em jogo para proteger o filho.','Intolerância, memória do Holocausto e resistência afetiva.','A Vida é Bela (1997) lembra que a intolerância institucionalizada começa com discursos aceitos como normais.','introducao','from-yellow-500/30 to-neutral-900/60','https://upload.wikimedia.org/wikipedia/pt/a/af/La_vita_%C3%A8_bella.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('nise','Nise: O Coração da Loucura',2015,'Roberto Berliner',8.1,'A psiquiatra Nise da Silveira recusa métodos violentos e trata pacientes com arte e afeto.','Reforma psiquiátrica, humanização da saúde e protagonismo feminino na ciência.','Nise (2015) prova que humanizar o cuidado é mais eficaz do que discipliná-lo pela força.','conclusao','from-teal-400/30 to-purple-950/60','https://upload.wikimedia.org/wikipedia/pt/1/19/Nise-_O_Cora%C3%A7%C3%A3o_da_Loucura.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('temporada-de-caca','Aquarius',2016,'Kleber Mendonça Filho',7.6,'Clara resiste à pressão de uma construtora para deixar o apartamento onde viveu a vida inteira.','Direito à cidade, especulação imobiliária e envelhecimento.','Aquarius (2016) mostra que a cidade também expulsa pela pressão econômica, sem precisar de decreto.','desenvolvimento','from-cyan-400/30 to-rose-900/50','https://upload.wikimedia.org/wikipedia/pt/8/80/Aquarius_%28filme%29.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('democracia-em-vertigem','Democracia em Vertigem',2019,'Petra Costa',7.2,'Documentário sobre a crise política brasileira recente a partir de uma perspectiva pessoal.','Polarização, instituições e papel da imprensa.','Democracia em Vertigem (2019) evidencia como a erosão da confiança nas instituições fragiliza a democracia.','desenvolvimento','from-green-500/30 to-blue-950/60','https://upload.wikimedia.org/wikipedia/pt/e/e0/Democracia_em_Vertigem.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('nosso-lar','Que Horas São Aí?',2001,'Tsai Ming-liang',7.5,'Um vendedor de relógios em Taipé vive o luto e a distância em uma cidade indiferente.','Solidão urbana e saúde mental nas grandes cidades.','Que Horas São Aí? (2001) retrata a solidão que se instala mesmo em meio à multidão urbana.','introducao','from-blue-400/30 to-zinc-950/60','https://upload.wikimedia.org/wikipedia/en/c/ce/Whattimeisitthere.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('bicho-de-sete-cabecas','Bicho de Sete Cabeças',2001,'Laís Bodanzky',8.1,'Um jovem é internado à força pelo pai em um manicômio e enfrenta a violência da instituição.','Internação compulsória, relações familiares e reforma psiquiátrica.','Bicho de Sete Cabeças (2001) denuncia instituições que tratam o sofrimento psíquico como desvio a ser punido.','desenvolvimento','from-red-400/30 to-indigo-950/60','https://upload.wikimedia.org/wikipedia/pt/0/0e/Bicho_de_Sete_Cabe%C3%A7as_poster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('infancia-roubada','Que Bom Te Ver Viva',1989,'Lúcia Murat',7.4,'Depoimentos de mulheres que sobreviveram à tortura durante a ditadura militar brasileira.','Memória, justiça de transição e violência de Estado contra mulheres.','Que Bom Te Ver Viva (1989) mostra que as marcas da violência de Estado atravessam gerações.','conclusao','from-purple-500/30 to-stone-950/60','https://upload.wikimedia.org/wikipedia/pt/d/d4/Que_Bom_Te_Ver_Viva.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('o-jardineiro-fiel','O Jardineiro Fiel',2005,'Fernando Meirelles',7.4,'Um diplomata investiga a morte da esposa e descobre testes farmacêuticos ilegais na África.','Ética na saúde, poder corporativo e desigualdade global.','O Jardineiro Fiel (2005) alerta para a exploração de populações vulneráveis em nome do lucro farmacêutico.','desenvolvimento','from-emerald-500/30 to-red-950/60','https://upload.wikimedia.org/wikipedia/pt/e/ec/The_Constant_Gardener.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('erin-brockovich','Erin Brockovich',2000,'Steven Soderbergh',7.4,'Uma mãe solo sem formação jurídica enfrenta uma empresa que contaminou a água de uma cidade.','Contaminação ambiental, acesso à justiça e protagonismo feminino.','Erin Brockovich (2000) mostra que a mobilização cidadã pode romper o silêncio de grandes corporações.','conclusao','from-amber-400/30 to-cyan-950/60','https://upload.wikimedia.org/wikipedia/pt/7/75/Erin_Brockovich_poster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('a-caminho-de-casa','Lion: Uma Jornada Para Casa',2016,'Garth Davis',8,'Um menino indiano se perde da família, é adotado na Austrália e usa mapas digitais para reencontrar sua origem.','Infância vulnerável, adoção e tecnologia com uso social.','Lion (2016) evidencia que a tecnologia ganha sentido quando reconstrói vínculos, e não quando os substitui.','conclusao','from-orange-400/30 to-blue-950/60','https://upload.wikimedia.org/wikipedia/pt/7/70/Lion_%28filme%29.png');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('a-corrente-do-bem','A Corrente do Bem',2000,'Mimi Leder',7.2,'Um menino cria um projeto escolar de gentileza em cadeia que transforma sua comunidade.','Proposta de intervenção com foco em empatia, escola e ação comunitária.','A Corrente do Bem (2000) demonstra que mudanças estruturais começam por gestos coletivos multiplicáveis.','conclusao','from-yellow-400/30 to-teal-950/60','https://upload.wikimedia.org/wikipedia/en/d/da/Pay_it_forward_ver1.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('estamira','Estamira',2004,'Marcos Prado',8.3,'Retrato de uma mulher com transtorno mental que vive há décadas em um aterro no Rio de Janeiro.','Catadores, resíduos sólidos e invisibilidade social.','Estamira (2004) mostra que a sociedade descarta pessoas com a mesma naturalidade com que descarta lixo.','introducao','from-lime-400/30 to-neutral-950/60','cartaz-estamira.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('o-menino-do-pijama','O Menino do Pijama Listrado',2008,'Mark Herman',7.7,'A amizade entre o filho de um oficial nazista e um menino judeu revela o absurdo da segregação.','Intolerância, doutrinação e infância diante do preconceito.','O Menino do Pijama Listrado (2008) mostra que o preconceito é aprendido, nunca natural.','introducao','from-slate-300/30 to-blue-950/60','https://upload.wikimedia.org/wikipedia/pt/1/1f/The_Boy_in_the_Striped_Pyjamas.png');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('garotas-de-programa','Milk: A Voz da Igualdade',2008,'Gus Van Sant',7.5,'Harvey Milk se torna o primeiro político abertamente gay eleito na Califórnia e luta por direitos civis.','Direitos LGBTQIA+, representatividade política e cidadania.','Milk (2008) lembra que a conquista de direitos depende de representação nos espaços de decisão.','desenvolvimento','from-pink-500/30 to-indigo-950/60','https://upload.wikimedia.org/wikipedia/pt/3/32/MilkPoster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('intocaveis','Intocáveis',2011,'Olivier Nakache',8.5,'Um aristocrata tetraplégico contrata um cuidador da periferia e ambos rompem barreiras sociais.','Acessibilidade, capacitismo e inclusão no mercado de trabalho.','Intocáveis (2011) evidencia que a maior barreira enfrentada por pessoas com deficiência é social, não física.','desenvolvimento','from-amber-300/30 to-slate-950/60','https://upload.wikimedia.org/wikipedia/pt/d/d6/Intouchables_cartaz.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('extraordinario','Extraordinário',2017,'Stephen Chbosky',7.9,'Auggie, um menino com deformidade facial, entra na escola regular e enfrenta o olhar dos colegas.','Bullying escolar, inclusão e empatia; ótimo para propostas de intervenção pedagógicas.','Extraordinário (2017) mostra que a escola inclusiva se constrói na convivência, não apenas na matrícula.','conclusao','from-sky-400/30 to-violet-950/60','https://upload.wikimedia.org/wikipedia/pt/f/f1/Wonder_%28filme%29.png');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('nomadland','Nomadland',2020,'Chloé Zhao',7.3,'Após perder tudo na crise econômica, Fern vive em uma van e trabalha em empregos temporários.','Precarização do trabalho, envelhecimento e crise habitacional.','Nomadland (2020) revela o rosto da precarização: trabalhar a vida inteira e envelhecer sem teto.','desenvolvimento','from-orange-300/30 to-blue-950/60','https://upload.wikimedia.org/wikipedia/pt/9/94/Nomadland_%28cartaz%29.png');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('vidas-secas','Vidas Secas',1963,'Nelson Pereira dos Santos',7.9,'Uma família de retirantes atravessa o sertão fugindo da seca e da miséria, sem terra e sem direitos.','Clássico do Cinema Novo para seca, migração forçada e fome no Nordeste.','Vidas Secas (1963) mostra que a seca só vira tragédia quando somada ao abandono do poder público.','introducao','from-yellow-700/40 to-stone-950/60','https://upload.wikimedia.org/wikipedia/pt/7/7f/Vidas_Secas_CN_0116A.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('roma','Roma',2018,'Alfonso Cuarón',7.7,'Cleo é empregada doméstica de uma família de classe média na Cidade do México dos anos 1970.','Trabalho doméstico, maternidade e racismo estrutural na América Latina.','Roma (2018) revela o silêncio imposto a mulheres que sustentam casas alheias sem espaço na própria história.','desenvolvimento','from-slate-400/30 to-slate-950/60','https://upload.wikimedia.org/wikipedia/pt/f/f1/Roma_-_Poster.jpeg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('green-book','Green Book: O Guia',2018,'Peter Farrelly',8.2,'Um pianista negro percorre o sul segregado dos EUA guiado por um motorista branco e por um manual de sobrevivência racial.','Segregação institucional, convivência e desconstrução de preconceitos.','Green Book (2018) lembra que talento e prestígio não protegem quem é alvo do racismo institucional.','desenvolvimento','from-emerald-500/30 to-amber-950/60','https://upload.wikimedia.org/wikipedia/pt/f/f0/Green_Book_-_Poster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('12-anos-de-escravidao','12 Anos de Escravidão',2013,'Steve McQueen',8.1,'Solomon Northup, homem negro livre, é sequestrado e vendido como escravo nos Estados Unidos do século XIX.','Herança escravocrata, racismo estrutural e reparação histórica.','12 Anos de Escravidão (2013) evidencia que a escravidão moldou desigualdades que sobrevivem à sua abolição.','introducao','from-amber-700/40 to-neutral-950/60','https://upload.wikimedia.org/wikipedia/pt/d/dc/Twelve_Years_a_Slave.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('persepolis','Persépolis',2007,'Marjane Satrapi',8,'Marjane cresce no Irã da revolução islâmica e enfrenta o exílio e a perda de liberdades individuais.','Fundamentalismo, direitos das mulheres e condição de refugiada.','Persépolis (2007) mostra que restringir a liberdade feminina é o primeiro passo de todo projeto autoritário.','desenvolvimento','from-fuchsia-500/30 to-zinc-950/60','https://upload.wikimedia.org/wikipedia/pt/d/d6/Persepolis_poster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('o-sal-da-terra','O Sal da Terra',2014,'Wim Wenders',8.3,'A trajetória do fotógrafo Sebastião Salgado, entre tragédias humanitárias e o reflorestamento da Mata Atlântica.','Crise ambiental, recuperação de biomas e denúncia social pela imagem.','O Sal da Terra (2014) prova que a degradação ambiental pode ser revertida quando existe projeto coletivo.','conclusao','from-lime-600/30 to-emerald-950/60','https://upload.wikimedia.org/wikipedia/en/0/04/TheSaltoftheEarth2014.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('lixo-extraordinario','Lixo Extraordinário',2010,'Lucy Walker',8,'O artista Vik Muniz cria obras com catadores do aterro de Jardim Gramacho, no Rio de Janeiro.','Catadores, reciclagem e arte como ferramenta de dignidade.','Lixo Extraordinário (2010) mostra que reciclagem é também uma política de dignidade para quem vive do descarte.','conclusao','from-teal-500/30 to-stone-950/60','https://upload.wikimedia.org/wikipedia/pt/a/a2/Waste_Land-poster.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('selma','Selma: Uma Luta pela Igualdade',2014,'Ava DuVernay',7.5,'Martin Luther King lidera a marcha de Selma pelo direito ao voto da população negra nos EUA.','Participação política, movimentos sociais e conquista de direitos.','Selma (2014) reforça que direitos não são concedidos: são conquistados pela mobilização organizada.','conclusao','from-indigo-500/30 to-red-950/60','https://upload.wikimedia.org/wikipedia/pt/d/db/Selma_%28filme%29.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('eu-daniel-blake','Eu, Daniel Blake',2016,'Ken Loach',7.9,'Um carpinteiro doente enfrenta a burocracia do sistema de assistência britânico para receber auxílio.','Burocracia estatal, exclusão digital e proteção social.','Eu, Daniel Blake (2016) denuncia sistemas de proteção social que humilham justamente quem mais precisa deles.','desenvolvimento','from-blue-600/30 to-stone-950/60','https://upload.wikimedia.org/wikipedia/pt/8/8c/I%2C_Daniel_Blake.jpg');
INSERT OR REPLACE INTO filmes (id,titulo,ano,diretor,imdb,sinopse,como_usar,citacao,parte,cor,cartaz) VALUES ('escritores-da-liberdade','Escritores da Liberdade',2007,'Richard LaGravenese',7.5,'Uma professora usa a escrita de diários para transformar a vida de alunos marcados pela violência urbana.','Educação transformadora, escrita como resistência e propostas de intervenção escolares.','Escritores da Liberdade (2007) demonstra que dar voz aos estudantes é uma estratégia pedagógica contra a violência.','conclusao','from-rose-500/30 to-indigo-950/60','https://upload.wikimedia.org/wikipedia/pt/7/73/FWPoster.jpg');

